const input = $json;
const own = Object.prototype.hasOwnProperty;
const rawCandidate = own.call(input, 'candidate') ? input.candidate : undefined;
let parsedCandidate = rawCandidate;
let parserStatus = 'parsed';
const validationErrors = [];

const addError = (code, path, message, detail = null) => {
  const entry = { code, path, message };
  if (detail !== null) entry.detail = detail;
  validationErrors.push(entry);
};

if (typeof rawCandidate === 'string') {
  try {
    parsedCandidate = JSON.parse(rawCandidate);
  } catch (error) {
    parserStatus = 'failed';
    parsedCandidate = null;
    addError('MALFORMED_JSON', '$', 'candidate string is not valid JSON', error.message);
  }
}

if (parserStatus === 'parsed') {
  const isPlainObject = parsedCandidate !== null
    && typeof parsedCandidate === 'object'
    && !Array.isArray(parsedCandidate)
    && Object.prototype.toString.call(parsedCandidate) === '[object Object]';

  if (!isPlainObject) {
    addError('NOT_OBJECT', '$', 'candidate must be a plain JSON object');
  } else {
    const required = ['action_id', 'target', 'reason', 'requires_approval'];
    const allowed = new Set(required);

    for (const field of required) {
      if (!own.call(parsedCandidate, field)) {
        addError('MISSING_REQUIRED_FIELD', '$.' + field, field + ' is required by the frozen action contract');
      }
    }

    const unexpected = Object.keys(parsedCandidate).filter((field) => !allowed.has(field)).sort();
    for (const field of unexpected) {
      addError('UNEXPECTED_FIELD', '$.' + field, field + ' is not allowed because additionalProperties is false');
    }

    if (own.call(parsedCandidate, 'action_id')) {
      if (typeof parsedCandidate.action_id !== 'string' || !['fan_on', 'fan_off'].includes(parsedCandidate.action_id)) {
        addError('UNKNOWN_ACTION', '$.action_id', 'action_id must be the exact string fan_on or fan_off');
      }
    }

    if (own.call(parsedCandidate, 'target')) {
      if (typeof parsedCandidate.target !== 'string' || parsedCandidate.target !== 'fan_1') {
        addError('UNKNOWN_TARGET', '$.target', 'target must be the exact string fan_1');
      }
    }

    if (own.call(parsedCandidate, 'reason')) {
      if (typeof parsedCandidate.reason !== 'string' || parsedCandidate.reason.length < 1) {
        addError('INVALID_REASON', '$.reason', 'reason must be a string with minimum length 1');
      }
    }

    if (own.call(parsedCandidate, 'requires_approval')) {
      if (typeof parsedCandidate.requires_approval !== 'boolean') {
        addError('INVALID_APPROVAL_FLAG', '$.requires_approval', 'requires_approval must be a Boolean');
      }
    }
  }
}

const precedence = [
  'MALFORMED_JSON',
  'NOT_OBJECT',
  'MISSING_REQUIRED_FIELD',
  'UNEXPECTED_FIELD',
  'UNKNOWN_ACTION',
  'UNKNOWN_TARGET',
  'INVALID_REASON',
  'INVALID_APPROVAL_FLAG'
];
const schemaValid = validationErrors.length === 0;
const primaryCode = schemaValid
  ? 'VALID_ACTION'
  : precedence.find((code) => validationErrors.some((entry) => entry.code === code));
const rawType = rawCandidate === null ? 'null' : Array.isArray(rawCandidate) ? 'array' : typeof rawCandidate;

return [{ json: {
  ...input,
  candidate_received: rawCandidate === undefined ? null : rawCandidate,
  candidate_raw_type: rawType,
  parser_status: parserStatus,
  parsed_candidate: parsedCandidate,
  validation_status: schemaValid ? 'valid' : 'invalid',
  schema_valid: schemaValid,
  validation_reason_code: primaryCode,
  validation_errors: validationErrors,
  action: schemaValid ? parsedCandidate : null
} }];

const action = $json.action;
const actionAllowed = action !== null
  && typeof action === 'object'
  && ['fan_on', 'fan_off'].includes(action.action_id);
const targetAllowed = actionAllowed && action.target === 'fan_1';
let policyDecision;
let policyReasonCode;

if (!actionAllowed || !targetAllowed) {
  policyDecision = 'block';
  policyReasonCode = 'BLOCK_POLICY_ALLOWLIST_MISMATCH';
} else if (action.requires_approval === true) {
  policyDecision = 'approval_required';
  policyReasonCode = 'VALID_ACTION_REQUIRES_APPROVAL';
} else {
  policyDecision = 'allow';
  policyReasonCode = 'ALLOW_VALID_DIRECT_ACTION';
}

return [{ json: {
  ...$json,
  policy_executed: true,
  policy_decision: policyDecision,
  policy_reason_code: policyReasonCode,
  released_action: policyDecision === 'allow' ? action : null,
  held_action: policyDecision === 'approval_required' ? action : null
} }];

return [{ json: {
  ...$json,
  safety_decision: 'allow',
  terminal_stage: 'OBID_RUNTIME_POLICY_ALLOW',
  endpoint_reached: null
} }];

return [{ json: {
  ...$json,
  safety_decision: 'approval_required',
  terminal_stage: 'OBID_APPROVAL_REQUIRED_PENDING_STEP9',
  endpoint_reached: null
} }];

return [{ json: {
  ...$json,
  safety_decision: 'block',
  terminal_stage: 'OBID_RUNTIME_POLICY',
  endpoint_reached: null
} }];
